import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Days Asia- Scrub / Deep-scrub analysis","description":"","frontmatter":{"title":"Ceph Days Asia- Scrub / Deep-scrub analysis","date":"2024-10-04T00:00:00.000Z","updated":"2024-10-04T00:00:00.000Z","tags":["Ceph","Deep Scrub","Data Consistency","Storage Mechanism","Ceph Storage System"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_Days_Asia_-_Scrub_Deep-scrub_analysis.md","filePath":"posts/2024/Ceph_Days_Asia_-_Scrub_Deep-scrub_analysis.md","lastUpdated":1780459816000}'),r={name:"posts/2024/Ceph_Days_Asia_-_Scrub_Deep-scrub_analysis.md"};function s(o,a,n,u,h,p){return l(),t("div",null,[...a[0]||(a[0]=[i('<p>Ceph Days Asia 会议上，三星SDS的Jae-min Jae-min介绍了Ceph存储系统的深度清理（Deep Scrub）机制。以下是对会议内容的详细总结：</p><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议参与者" tabindex="-1">会议参与者 <a class="header-anchor" href="#会议参与者" aria-label="Permalink to &quot;会议参与者&quot;">​</a></h4><ul><li><strong>Jae-min Jae-min</strong> (三星SDS)</li></ul><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><ul><li>Ceph存储系统的深度清理（Deep Scrub）机制</li></ul><h4 id="会议内容总结" tabindex="-1">会议内容总结 <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结&quot;">​</a></h4><ol><li><p><strong>公司介绍</strong></p><ul><li>三星SDS是三星集团内部的IT服务公司，主要负责创建和运营计算数据系统。</li><li>公司拥有两个主要平台：SCP（类似AWS）和三星云平台（Cello Square）。</li><li>三星SDS在全球40个国家设有58个分支机构和18个数据中心，服务众多国内外知名客户。</li></ul></li><li><p><strong>深度清理（Deep Scrub）机制</strong></p><ul><li><strong>概念介绍</strong>：深度清理是Ceph存储系统中用于检测和修复数据一致性的过程。</li><li><strong>数据存储机制</strong>：在Ceph中，对象存储时附带元数据，这些元数据存储在PG（Placement Group）相关的tangent中。</li><li><strong>问题背景</strong>：由于深度清理机制，一些用户可能遇到了困难，公司因此深入研究了源代码层面的问题。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>详细解释深度清理机制的具体步骤和原理。</li><li>提供相关培训和文档，帮助用户理解和应用。</li></ul><h4 id="会议结论" tabindex="-1">会议结论 <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;会议结论&quot;">​</a></h4><ul><li>深度清理是确保Ceph存储系统数据一致性和可靠性的关键机制，需要用户和开发者深入理解其工作原理和操作方法。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到的“tangent”可能是与PG相关的某种数据结构或存储方式，具体细节需进一步确认。</li></ul><p>以上是会议的详细纪要，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',15)])])}const d=e(r,[["render",s]]);export{_ as __pageData,d as default};
